#[derive(Clone, Copy, Default, Debug)]
pub struct WorldParticles<'a> {
    pub particle_id: i32,
    pub long_distance: bool,
    pub x: f32,
    pub y: f32,
    pub z: f32,
    pub offset_x: f32,
    pub offset_y: f32,
    pub offset_z: f32,
    pub particle_data: f32,
    pub particles: i32,
    pub data: Array<'a, VarInt>,
}

static VAR_WORLDPARTICLES: [u8; 6] = [0,0,0,0,0,0];
impl<'a> WorldParticles<'a> {
    pub fn decode(r: &mut Reader<'a>, v: Version) -> Option<Self> {
        let ctx = 0i32;
        let mut o = Self::default();
        match VAR_WORLDPARTICLES[v as usize] {
            0 => {
            o.particle_id = r.i32();
            o.long_distance = r.bool();
            o.x = r.f32();
            o.y = r.f32();
            o.z = r.f32();
            o.offset_x = r.f32();
            o.offset_y = r.f32();
            o.offset_z = r.f32();
            o.particle_data = r.f32();
            o.particles = r.i32();
            if (o.particle_id as i64) == 36 {
                o.data = Array::parse(r, 2, v, 0)?;
            }
            if (o.particle_id as i64) == 37 || (o.particle_id as i64) == 38 {
                o.data = Array::parse(r, 1, v, 0)?;
            }
            }
            _ => return None,
        }
        if r.err { None } else { Some(o) }
    }
}
